import math

def is_perfect_square(n):
    if n < 1:
        return False
    root = int(math.isqrt(n))
    return root * root == n

def is_cool(n):
    """
    Checks if n is a cool integer using backtracking search.
    n is cool if there exists a permutation (x_1, ..., x_n) of (1, ..., n)
    such that no prefix sum is a perfect square.
    """
    if n == 0:
        return False

    # State: used array tracks numbers already in the permutation
    used = [False] * (n + 1)

    # We don't need to store the path explicitly, just the current sum and the count of elements placed.

    def solve(current_sum, count):
        if count == n:
            # Found a full permutation satisfying the condition
            return True

        # Try every available number x
        for x in range(1, n + 1):
            if not used[x]:
                new_sum = current_sum + x

                if not is_perfect_square(new_sum):
                    # Valid move, recurse
                    used[x] = True
                    if solve(new_sum, count + 1):
                        return True
                    # Backtrack
                    used[x] = False

        # No available number leads to a valid completion from this state
        return False

    return solve(0, 0)

# Test for n from 1 to 15
cool_integers = []
for n in range(1, 16):
    if is_cool(n):
        cool_integers.append(n)

print(f"Cool integers up to 15: {cool_integers}")

