import math
import time

def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_tsn(n):
    # Check if the total sum S_n is a perfect square
    s_n = n * (n + 1) // 2
    return is_square(s_n)

def is_cool_backtrack(n):
    # State: (current_sum, used_mask)

    # Optimization: Check necessary condition first
    if check_tsn(n):
        return False

    # Initial call: Start with empty permutation
    # Used set tracks numbers {1, 2, ..., n} already in the permutation
    used = [False] * (n + 1)

    def backtrack(k, current_sum):
        # k is the current length of the permutation (0 to n-1)
        if k == n:
            # Successfully built a permutation of length n
            return True

        # Try every available number x from 1 to n
        for x in range(1, n + 1):
            if not used[x]:
                new_sum = current_sum + x

                # Condition check: New prefix sum must NOT be a square
                if not is_square(new_sum):
                    used[x] = True
                    if backtrack(k + 1, new_sum):
                        return True
                    used[x] = False # Backtrack

        return False

    # Start the search
    return backtrack(0, 0)

def main():
    N_MAX = 500
    print(f"Starting coolness search for N=1 to {N_MAX}...")
    start_time = time.time()

    cool_count = 0
    cool_list = []

    for n in range(1, N_MAX + 1):
        if n % 3 == 1 and n > 1:
            # Skip based on W4 conjecture, for speed/initial filtering, 
            # although the task implies testing all N.
            pass 

        if is_cool_backtrack(n):
            cool_count += 1
            cool_list.append(n)

            # Log progress periodically
            if n % 50 == 0:
                print(f"Progress: N={n}/{N_MAX}. Count={cool_count}")
        else:
            if n % 50 == 0:
                print(f"Progress: N={n}/{N_MAX}. Count={cool_count}")

    end_time = time.time()

    print("-" * 30)
    print(f"Search Complete.")
    print(f"Time taken: {end_time - start_time:.2f} seconds")
    print(f"Total cool integers found up to N={N_MAX}: {cool_count}")
    # print(f"Cool integers found: {cool_list}") # Too long to print

    return cool_count, cool_list

# Execute the main function and capture results
result = main()
